const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const cities = {
        'Beijing': ee.Geometry.Point([116.4074, 39.9042]),
        'Chongqing': ee.Geometry.Point([106.5516, 29.5630]),
        'Wuhan': ee.Geometry.Point([114.3055, 30.5928])
    };

    const dateRangeBefore = { start: '2020-01-01', end: '2020-01-20' };
    const dateRangeDuring = { start: '2020-02-10', end: '2020-02-25' };
    const band = 'tropospheric_NO2_column_number_density';
    const scale = 3000;

    // 2. Data Acquisition & Pre-processing Function
    const getMeanNO2 = function(geometry, dateRange) {
        const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
            .filterBounds(geometry)
            .filterDate(dateRange.start, dateRange.end)
            .select([band, 'qa_value']);

        // Check for empty collection
        if (collection.size().getInfo() === 0) {
            return { mean: null, pixels: 0, images: 0 };
        }

        // Apply quality assurance mask
        const maskedCollection = collection.map(function(image) {
            const qaMask = image.select('qa_value').gt(0.75);
            return image.updateMask(qaMask);
        });

        const meanImage = maskedCollection.select(band).mean();

        // Calculate statistics
        const stats = meanImage.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: geometry,
            scale: scale,
            maxPixels: 1e9
        });

        const meanVal = stats.get(band + '_mean').getInfo();
        const pixelCount = stats.get(band + '_count').getInfo();

        return {
            mean: meanVal,
            pixels: pixelCount,
            images: collection.size().getInfo()
        };
    };

    let all_decreased = true;
    const cityNames = Object.keys(cities);

    for (const cityName of cityNames) {
        const geom = cities[cityName].buffer(25000); // 25km buffer for metro area

        // 3. Calculation for both periods
        const before = getMeanNO2(geom, dateRangeBefore);
        const during = getMeanNO2(geom, dateRangeDuring);

        // 4. Validation & Intermediate Output
        if (before.images === 0 || during.images === 0) {
            console.log(`Data missing for ${cityName} in one or both periods.`);
            console.log("A: No");
            return;
        }
        if (before.pixels === 0 || during.pixels === 0) {
            console.log(`No valid pixels for ${cityName} after QA filtering.`);
            console.log("A: No");
            return;
        }
        if (before.mean === null || during.mean === null) {
            console.log(`Calculation failed for ${cityName}.`);
            console.log("C3: Calculation Failure");
            return;
        }

        const decrease = during.mean < before.mean;
        const change_pct = ((during.mean - before.mean) / before.mean) * 100;

        console.log(`${cityName}:`);
        console.log(`  Jan (before): ${before.mean.toExponential(3)} mol/m^2 (${before.images} images)`);
        console.log(`  Feb (during): ${during.mean.toExponential(3)} mol/m^2 (${during.images} images)`);
        console.log(`  Change: ${change_pct.toFixed(2)}%`);
        console.log(`  Status: ${decrease ? 'Decreased' : 'Increased/Same'}`);

        if (!decrease) {
            all_decreased = false;
        }
    }

    // 5. Final Answer
    if (all_decreased) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
